const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 1: Development of the Self in Society (Term 1)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch1_lesson1 = [
  t(1, '## Development of the Self in Society\n\nUnderstanding who you are is the starting point for living a fulfilled and responsible life. In Grade 10 Life Orientation, we explore the concepts of self-awareness, self-esteem, self-image, and self-concept — foundational ideas that influence your choices, relationships, and future.\n\n### Self-Concept, Self-Esteem, and Self-Image\n\nThese three terms are related but have distinct meanings:\n\n| Term | Definition | Example |\n|------|-----------|----------|\n| **Self-concept** | The overall idea or mental picture you have of yourself — who you believe you are | "I am a hard-working student who is good at sport and a loyal friend" |\n| **Self-esteem** | How you feel about yourself — your sense of personal worth or value | "I feel confident about my abilities and believe I deserve respect" |\n| **Self-image** | How you see your physical appearance and how you think others see you | "I think I look good in my school uniform and present myself neatly" |\n\nYour self-concept is the broadest term: it includes both self-esteem (emotional) and self-image (physical). A healthy self-concept means having a realistic, mostly positive view of who you are, while accepting areas where you can improve.'),
  t(2, '### Factors That Influence Self-Concept\n\nYour self-concept is not fixed — it develops over time and is shaped by many factors:\n\n**Family:** The messages you receive from parents, siblings, and extended family in childhood lay the foundation. Encouragement builds confidence; constant criticism can undermine self-worth.\n\n**Peers and friends:** During adolescence, peer opinion becomes very powerful. Being accepted boosts self-esteem, while bullying, exclusion, or peer pressure can damage it.\n\n**Media and social media:** Images of "ideal" bodies, lifestyles, and success on platforms like Instagram, TikTok, and television create unrealistic standards. In South Africa, advertising often promotes narrow beauty ideals that do not reflect the diversity of our population.\n\n**Culture and community:** Cultural norms around gender, age, and achievement influence how you see yourself. Ubuntu — "I am because we are" — reminds us that our identity is shaped within community.\n\n**School and teachers:** Academic feedback, participation in extramurals, and the school environment all contribute. Positive reinforcement from teachers can be life-changing.\n\n**Personal experiences:** Successes, failures, trauma, and achievements all shape your self-concept over time.'),
  q(3, 'Which of the following BEST describes the difference between self-esteem and self-image?',
    ['Self-esteem is how you feel about your worth; self-image is how you see your physical appearance', 'They are the same thing expressed differently', 'Self-esteem relates to physical health; self-image relates to mental health', 'Self-image is more important than self-esteem'], 0,
    'Self-esteem is the emotional dimension — your sense of personal value and confidence. Self-image is the physical dimension — how you perceive your appearance. Both are components of self-concept.'),
  t(4, '### Strategies to Build Healthy Self-Esteem\n\nBuilding self-esteem is a process that requires deliberate effort:\n\n**Positive self-talk:** Replace negative inner dialogue ("I am useless") with realistic, encouraging thoughts ("I made a mistake, but I can learn from it"). The way you speak to yourself matters.\n\n**Set achievable goals:** Break large goals into smaller steps. Each small success builds confidence.\n\n**Celebrate your strengths:** Make a list of things you are good at. Everyone has strengths — find yours and develop them.\n\n**Accept imperfections:** Nobody is perfect. Acknowledge areas for growth without harsh self-judgement.\n\n**Surround yourself with positive people:** Spend time with friends and family who encourage and support you, not those who put you down.\n\n**Help others:** Volunteering and acts of kindness boost your sense of purpose and value.\n\n**Limit social media comparison:** Remember that social media shows a curated, filtered version of life. Do not compare your real life to someone else\'s highlight reel.\n\n**Seek help when needed:** Talk to a trusted adult, school counsellor, or contact Childline (0800 055 555) if you are struggling with low self-esteem.'),
  fb(5, 'The overall mental picture you have of yourself is called your ___. The African philosophy that reminds us our identity is shaped within community is called ___.',
    ['self-concept', 'ubuntu'],
    'Self-concept is the broad term encompassing self-esteem and self-image. Ubuntu is the African philosophy meaning "I am because we are," emphasising communal identity.'),
  t(6, '### Power and Power Relations\n\nPower affects relationships at every level of society. Understanding power helps you recognise when it is used fairly and when it becomes abusive.\n\n**Types of power:**\n- **Personal power:** Confidence, knowledge, and skills that empower you to make decisions\n- **Social power:** Influence gained from status, popularity, or group membership\n- **Institutional power:** Authority held by organisations such as government, schools, and employers\n- **Economic power:** Control over money and resources\n\n**Power relations in South Africa:**\nSouth Africa\'s history of colonialism and apartheid created extreme power imbalances based on race. Although the Constitution now guarantees equality, power imbalances persist in many areas:\n- Gender: women and girls often have less power in families and communities\n- Age: adults may use authority to silence young people\'s voices\n- Economic: wealth disparities mean some communities have more influence than others\n- Knowledge: access to education determines who participates in decision-making\n\nHealthy power relations are characterised by mutual respect, shared decision-making, and accountability. Unhealthy power relations involve domination, coercion, and silencing of others.'),
  q(7, 'Lerato\'s teacher dismisses her opinion in class because "learners should listen, not speak." This is an example of:',
    ['An unhealthy power relation based on age and institutional authority', 'A healthy teacher-learner relationship', 'Constructive feedback from a caring teacher', 'Appropriate classroom management'], 0,
    'Using institutional authority (being the teacher) and age to silence a learner\'s voice is an unhealthy power relation. Respectful classrooms allow learners to express opinions while maintaining order.'),
  t(8, '### Masculinity, Femininity, and Gender Roles\n\nGender roles are the behaviours, activities, and responsibilities that society considers appropriate for males and females.\n\n**Traditional gender roles in South Africa:**\n\n| Males (traditional view) | Females (traditional view) |\n|--------------------------|---------------------------|\n| Provider and protector | Caregiver and homemaker |\n| Strong and unemotional | Nurturing and gentle |\n| Leader and decision-maker | Supportive and obedient |\n| Physical and sport-oriented | Domestic and family-oriented |\n\n**Why rigid gender roles are harmful:**\n- They limit individual potential — a boy who loves cooking or a girl who loves engineering should not be discouraged\n- They contribute to gender-based violence (GBV) when masculinity is linked to dominance and control\n- They place unfair burdens on both men and women\n- They do not reflect the reality of modern South Africa, where many women are breadwinners and many men are primary caregivers\n\n**The Constitution and gender:**\nSection 9 of the Bill of Rights prohibits unfair discrimination on the basis of gender, sex, and sexual orientation. South Africa was the first African country to legalise same-sex marriage (2006), recognising diverse gender identities and expressions.'),
  t(9, '### Differences and Respect\n\nSouth Africa is one of the most diverse countries in the world — 11 official languages, multiple cultures, religions, and traditions. Respecting differences is essential for social cohesion.\n\n**Types of differences:**\n- **Race and ethnicity:** South Africa\'s population includes Black, Coloured, Indian, and White communities, each with rich cultural traditions\n- **Gender and sexual orientation:** LGBTQI+ rights are protected by the Constitution\n- **Religion:** Christianity, Islam, Hinduism, Judaism, African traditional religions, and many others coexist\n- **Disability:** People with disabilities have the right to full participation in society\n- **Socio-economic status:** Poverty and wealth exist side by side in many communities\n\n**Stereotypes vs. reality:**\nA stereotype is an oversimplified, generalised belief about a group of people. Stereotypes are harmful because they reduce complex individuals to single characteristics and can lead to prejudice and discrimination.\n\n**Building respect for differences:**\n- Learn about cultures and traditions different from your own\n- Challenge stereotypes when you hear them\n- Use respectful language — avoid slurs, derogatory terms, and insensitive jokes\n- Listen to people\'s lived experiences rather than making assumptions\n- Remember: diversity is a strength, not a problem to be solved'),
  q(10, 'Which section of the South African Bill of Rights protects against unfair discrimination based on gender, race, and sexual orientation?',
    ['Section 9 (Equality)', 'Section 16 (Freedom of expression)', 'Section 24 (Environment)', 'Section 29 (Education)'], 0,
    'Section 9 of the Bill of Rights is the Equality clause. It prohibits unfair discrimination on grounds including race, gender, sex, pregnancy, marital status, ethnic or social origin, colour, sexual orientation, age, disability, religion, conscience, belief, culture, language, and birth.'),
  fb(11, 'Oversimplified, generalised beliefs about a group of people are called ___. Section ___ of the Bill of Rights is the Equality clause that prohibits unfair discrimination.',
    ['stereotypes', '9'],
    'Stereotypes reduce individuals to group-based assumptions and can lead to prejudice. Section 9 of the Bill of Rights guarantees equality and prohibits unfair discrimination.'),
];

